    //   new3.gdflix.io -> 302 -> new4.gdflix.io
    const HUBCLOUD_HOST = "hubcloud.ist";
    const GDFLIX_HOST   = "new6.gdflix.io";
    const HUB = "kdramasmaza.com.pk";

